BEGIN;
UPDATE demo_accounts SET balance=15
WHERE id=1;
SAVEPOINT trial;
UPDATE demo_accounts SET balance=99
WHERE id=2;
ROLLBACK TO trial;
RELEASE trial;
COMMIT;
